116			// Verify every object the target references, reading each once. This
117			// includes objects the delta omits because the base references them:
118			// certifying the delta requires those to be intact too. Only objects
119			// the base does not reference are carried. Digests are processed in
120			// sorted order so the package layout and any failure message are
121			// deterministic.
122			carry := digestsReferenced(target.Entries)
123			if baseSnap != nil {
124				for digest := range digestsReferenced(baseSnap.Entries) {
125					delete(carry, digest)
126				}
127			}
128			objects, err := s.writePackage(pin, absOut, mode, name, target, baseSnap, carry)
129			if err != nil {
130				return err
131			}
132			result = ExportResult{Name: name, Entries: len(target.Entries), Objects: objects}
133			return nil
134		})
