141	// writePackage stages the snapshot package as a complete temporary file
142	// inside the pinned parent directory and commits it via Store.commitOutput,
143	// which revalidates the destination immediately before the atomic rename. The
144	// document is streamed to the temporary file while each referenced object is
145	// verified, so neither object content nor the package text is ever held in
146	// memory. On any failure the temporary file is removed and an existing output
147	// is never touched. It returns the number of carried objects.
148	func (s *Store) writePackage(pin *parentPin, absOut string, mode os.FileMode, name string, target Snapshot, base *Snapshot, carry map[string]struct{}) (int, error) {
149		tmp, tmpBase, err := createTempIn(pin, ".package-")
150		if err != nil {
151			return 0, fmt.Errorf("cannot create temporary file for output: %w", err)
152		}
153		committed := false
