1	package vault
2	
3	import (
4		"os"
5		"path/filepath"
6		"reflect"
7		"sort"
8		"strings"
9		"testing"
10	)
11	
12	// TestListHealthyMapping establishes the healthy output contract: rows sorted
13	// by the complete artifact name, multi-level names shown verbatim, two names
14	// sharing one digest each getting a row, zero-byte artifacts listed normally,
15	// and a genuine {"entries":{}} listing zero rows without an error.
16	func TestListHealthyMapping(t *testing.T) {
17		root := filepath.Join(t.TempDir(), "vault")
18		store := New(root)
19	
20		// An initialized but empty repository: the explicit empty mapping lists
21		// successfully with no rows.
22		if err := store.Init(); err != nil {
23			t.Fatal(err)
24		}
25		if entries, err := store.List(); err != nil || len(entries) != 0 {
26			t.Fatalf("empty mapping: entries=%+v err=%v", entries, err)
27		}
28	
29		zero := writeInput(t, nil)
30		payload := writeInput(t, []byte("shared bytes\n"))
31		other := writeInput(t, []byte("other bytes\n"))
32		first, err := store.Put("z/last.bin", payload)
33		if err != nil {
34			t.Fatal(err)
35		}
36		second, err := store.Put("a/first.bin", payload) // shares first's object
37		if err != nil {
38			t.Fatal(err)
39		}
40		empty, err := store.Put("m/empty.bin", zero)
41		if err != nil {
42			t.Fatal(err)
43		}
44		if _, err := store.Put("mid.bin", other); err != nil {
45			t.Fatal(err)
46		}
47	
48		entries, err := store.List()
49		if err != nil {
50			t.Fatal(err)
51		}
52		gotNames := make([]string, 0, len(entries))
53		for _, e := range entries {
54			gotNames = append(gotNames, e.Name)
55		}
56		wantNames := []string{"a/first.bin", "m/empty.bin", "mid.bin", "z/last.bin"}
57		if !reflect.DeepEqual(gotNames, wantNames) {
58			t.Fatalf("names=%v, want %v", gotNames, wantNames)
59		}
60		byName := map[string]Entry{}
61		for _, e := range entries {
62			byName[e.Name] = e
63		}
64		// The shared digest yields two independent rows.
65		if second.Digest != first.Digest {
66			t.Fatalf("shared uploads disagree on digest: %+v vs %+v", first, second)
67		}
68		if byName["a/first.bin"].Digest != first.Digest ||
69			byName["z/last.bin"].Digest != first.Digest {
70			t.Fatalf("shared digest not preserved: %+v", entries)
71		}
72		if byName["m/empty.bin"].Size != 0 || byName["m/empty.bin"].Digest != empty.Digest {
73			t.Fatalf("zero-byte entry=%+v", byName["m/empty.bin"])
74		}
75		// Rows must be fully sorted by name even though puts were out of order.
76		if !sort.StringsAreSorted(gotNames) {
77			t.Fatalf("entries not sorted: %v", gotNames)
78		}
79	}
80	
81	// TestListRejectsUnusableCurrentIndex is the listing counterpart of the strict
82	// rules put/verify/snapshot enforce: artifact rows appear only when the whole
83	// mapping is complete, unambiguous, and every record is legal. Every damaged
84	// shape fails the whole list, returns no partial entries, names the concrete
85	// reason (duplicated key or offending mapping name), and leaves the index
86	// bytes untouched.
87	func TestListRejectsUnusableCurrentIndex(t *testing.T) {
88		goodDigest := digestOf("keep me")
89		validRecord := validRecordJSON("keep.txt", goodDigest, 7)
90		// A healthy record sitting beside the damage proves no partial list is
91		// returned: the good name must not show up either.
92		goodRow := `"keep.txt":` + validRecord
93		cases := map[string]struct {
94			index       string
95			wantInError string
96		}{
97			"bare null": {
98				index:       `null`,
99				wantInError: "expected a JSON object with an entries mapping",
100			},
101			"empty object": {
102				index:       `{}`,
103				wantInError: "missing entries mapping",
104			},
105			"null entries": {
106				index:       `{"entries":null}`,
107				wantInError: "missing entries mapping",
108			},
109			"array entries": {
110				index:       `{"entries":[]}`,
111				wantInError: "cannot unmarshal",
112			},
113			"string entries": {
114				index:       `{"entries":"none"}`,
115				wantInError: "cannot unmarshal",
116			},
117			"number entries": {
118				index:       `{"entries":3}`,
119				wantInError: "cannot unmarshal",
120			},
121			"truncated document": {
122				index:       `{"entries":{`,
123				wantInError: "unexpected end of JSON input",
124			},
125			"trailing content": {
126				index:       `{"entries":{}} {}`,
127				wantInError: "invalid character",
128			},
129			"top level array": {
130				index:       `[]`,
131				wantInError: "expected a JSON object with an entries mapping",
132			},
133			"duplicate entries field": {
134				index:       `{"entries":null,"entries":{}}`,
135				wantInError: `duplicate key "entries"`,
136			},
137			"duplicate artifact name": {
138				index:       `{"entries":{` + goodRow + `,"keep.txt":` + validRecord + `}}`,
139				wantInError: `duplicate key "keep.txt"`,
140			},
141			"same name through unicode escape": {
142				index: `{"entries":{` +
143					`"a/b":{"name":"a/b","digest":"` + goodDigest + `","size":7,"createdAt":"2026-01-01T00:00:00Z"},` +
144					`"a` + `\` + `u002fb":{"name":"a/b","digest":"` + goodDigest + `","size":7,"createdAt":"2026-01-01T00:00:00Z"}` +
145					`}}`,
146				wantInError: `duplicate key "a/b"`,
147			},
148			"duplicate field inside record": {
149				index: `{"entries":{"keep.txt":{"name":"keep.txt","digest":"` + goodDigest +
150					`","size":7,"size":8,"createdAt":"2026-01-01T00:00:00Z"}}}`,
151				wantInError: `duplicate key "size"`,
152			},
153			"good row beside a key mismatch": {
154				index: `{"entries":{` + goodRow + `,` +
155					`"other.txt":{"name":"wrong.txt","digest":"` + goodDigest +
156					`","size":7,"createdAt":"2026-01-01T00:00:00Z"}}}`,
157				wantInError: `entry "wrong.txt" is filed under "other.txt"`,
158			},
159			"good row beside an illegal name": {
160				index: `{"entries":{` + goodRow + `,` +
161					`"../evil":{"name":"../evil","digest":"` + goodDigest +
162					`","size":7,"createdAt":"2026-01-01T00:00:00Z"}}}`,
163				wantInError: `invalid entry name "../evil"`,
164			},
165			"good row beside a bad digest": {
166				index: `{"entries":{` + goodRow + `,` +
167					`"other.txt":{"name":"other.txt","digest":"XYZ","size":7,` +
168					`"createdAt":"2026-01-01T00:00:00Z"}}}`,
169				wantInError: "want 64 lowercase hex characters",
170			},
171			"good row beside a negative size": {
172				index: `{"entries":{` + goodRow + `,` +
173					`"other.txt":{"name":"other.txt","digest":"` + goodDigest +
174					`","size":-9,"createdAt":"2026-01-01T00:00:00Z"}}}`,
175				wantInError: "negative size",
176			},
177		}
178		for label, tc := range cases {
179			t.Run(label, func(t *testing.T) {
180				root := filepath.Join(t.TempDir(), "vault")
181				store := New(root)
182				if _, err := store.Put("keep.txt", writeInput(t, []byte("keep me"))); err != nil {
183					t.Fatal(err)
184				}
185				indexPath := filepath.Join(root, "index.json")
186				if err := os.WriteFile(indexPath, []byte(tc.index), 0o644); err != nil {
187					t.Fatal(err)
188				}
189	
190				entries, err := store.List()
191				if err == nil {
192					t.Fatal("expected list over a corrupt index to fail")
193				}
194				if entries != nil {
195					t.Fatalf("failed list returned usable partial entries: %+v", entries)
196				}
197				msg := err.Error()
198				if !strings.Contains(msg, "current index is corrupt") {
199					t.Fatalf("error %q does not identify the current index as corrupt", msg)
200				}
201				if !strings.Contains(msg, tc.wantInError) {
202					t.Fatalf("error %q does not indicate %q", msg, tc.wantInError)
203				}
204	
205				// Listing never repairs or rewrites the damaged bytes.
206				got, err := os.ReadFile(indexPath)
207				if err != nil {
208					t.Fatal(err)
209				}
210				if string(got) != tc.index {
211					t.Fatalf("index was rewritten\nwas: %s\nnow: %s", tc.index, got)
212				}
213			})
214		}
215	}
