217	// TestListReportsFirstBadRecordDeterministically names the alphabetically
218	// first offending mapping name when several records are bad.
219	func TestListReportsFirstBadRecordDeterministically(t *testing.T) {
220		goodDigest := digestOf("good")
221		index := `{"entries":{` +
222			`"zeta":{"name":"zeta","digest":"nope","size":0,"createdAt":"2026-01-01T00:00:00Z"},` +
223			`"alpha":{"name":"alpha","digest":"` + goodDigest + `","size":-3,"createdAt":"2026-01-01T00:00:00Z"}` +
224			`}}`
225		root := filepath.Join(t.TempDir(), "vault")
226		store := New(root)
227		if err := store.Init(); err != nil {
228			t.Fatal(err)
229		}
230		if err := os.WriteFile(filepath.Join(root, "index.json"), []byte(index), 0o644); err != nil {
231			t.Fatal(err)
232		}
233		entries, err := store.List()
234		if err == nil {
235			t.Fatal("expected list to fail")
236		}
237		if entries != nil {
238			t.Fatalf("partial list returned: %+v", entries)
239		}
240		if !strings.Contains(err.Error(), `entry "alpha"`) {
241			t.Fatalf("error %q does not name the alphabetically first bad record alpha", err)
242		}
243	}
244	
245	// TestListMissingRepositoryReportsUninitialized distinguishes a repository
246	// that was never initialized from an empty list: both a missing root and a
247	// directory with no index.json fail rather than listing zero artifacts.
248	func TestListMissingRepositoryReportsUninitialized(t *testing.T) {
249		missing := filepath.Join(t.TempDir(), "no-vault")
250		if entries, err := New(missing).List(); err == nil {
251			t.Fatalf("missing root listed %+v instead of failing", entries)
252		} else if !strings.Contains(err.Error(), "not initialized") {
253			t.Fatalf("error %q does not report the repository as uninitialized", err)
254		}
255	
256		root := filepath.Join(t.TempDir(), "vault")
257		store := New(root)
258		if err := os.MkdirAll(root, 0o755); err != nil {
259			t.Fatal(err)
260		}
261		// Directory present with a lock file but no index.json: still not
262		// initialized, never an empty list.
263		if entries, err := store.List(); err == nil {
264			t.Fatalf("missing index.json listed %+v instead of failing", entries)
265		} else if !strings.Contains(err.Error(), "not initialized") {
266			t.Fatalf("error %q does not report the repository as uninitialized", err)
267		}
268	}
269	
270	// TestListUnreadableIndexNotCorrupt distinguishes bytes that cannot be read
271	// from bytes that are present but malformed.
272	func TestListUnreadableIndexNotCorrupt(t *testing.T) {
273		if os.Getuid() == 0 {
274			t.Skip("permission-based unreadability cannot be tested as root")
275		}
276		root := filepath.Join(t.TempDir(), "vault")
277		store := New(root)
278		if _, err := store.Put("keep.txt", writeInput(t, []byte("keep me"))); err != nil {
279			t.Fatal(err)
280		}
281		indexPath := filepath.Join(root, "index.json")
282		if err := os.Chmod(indexPath, 0o000); err != nil {
283			t.Fatal(err)
284		}
285		t.Cleanup(func() { _ = os.Chmod(indexPath, 0o644) })
286	
287		entries, err := store.List()
288		if err == nil {
289			t.Fatal("expected list over an unreadable index to fail")
290		}
291		if entries != nil {
292			t.Fatalf("unreadable index returned entries: %+v", entries)
293		}
294		msg := err.Error()
295		if !strings.Contains(msg, "current index cannot be read") {
296			t.Fatalf("error %q does not say the index cannot be read", msg)
297		}
298		if strings.Contains(msg, "corrupt") {
299			t.Fatalf("an unreadable index must not be called corrupt: %q", msg)
300		}
301	}
302	
303	// TestListIgnoresObjectsAndSnapshots proves list reads only the current
304	// mapping: a missing or content-damaged object and a damaged snapshot record
305	// never block the legal current records, and listing changes nothing.
306	func TestListIgnoresObjectsAndSnapshots(t *testing.T) {
307		root := filepath.Join(t.TempDir(), "vault")
308		store := New(root)
309		entry, err := store.Put("keep.txt", writeInput(t, []byte("real bytes\n")))
310		if err != nil {
311			t.Fatal(err)
312		}
313		if _, err := store.CreateSnapshot("snap"); err != nil {
314			t.Fatal(err)
315		}
316		indexBefore, err := os.ReadFile(filepath.Join(root, "index.json"))
317		if err != nil {
318			t.Fatal(err)
319		}
320	
321		// Remove the referenced object: the row must still list.
322		object := filepath.Join(root, "objects", entry.Digest)
323		if err := os.Remove(object); err != nil {
324			t.Fatal(err)
325		}
326		if entries, err := store.List(); err != nil || len(entries) != 1 || entries[0].Name != "keep.txt" {
327			t.Fatalf("missing object blocked listing: entries=%+v err=%v", entries, err)
328		}
329	
330		// Restore a same-size, wrong-content object: listing still does not read it.
331		if err := os.WriteFile(object, []byte("different bytes!!"), 0o644); err != nil {
332			t.Fatal(err)
333		}
334		if entries, err := store.List(); err != nil || len(entries) != 1 {
335			t.Fatalf("damaged object blocked listing: entries=%+v err=%v", entries, err)
336		}
337	
338		// Damage a snapshot record: current mapping lists unaffected.
339		if err := os.WriteFile(filepath.Join(root, "snapshots", "snap.json"),
340			[]byte("{broken"), 0o644); err != nil {
341			t.Fatal(err)
342		}
343		if entries, err := store.List(); err != nil || len(entries) != 1 || entries[0].Digest != entry.Digest {
344			t.Fatalf("damaged snapshot blocked listing: entries=%+v err=%v", entries, err)
345		}
